  let pendingProject=null,projectLoadSerial=0;
  function smallProjectPreview(source,w,h){const scale=Math.min(1,480/w,360/h),c=canvas(Math.max(1,Math.round(w*scale)),Math.max(1,Math.round(h*scale)));if(source)context(c).drawImage(source,0,0,c.width,c.height);else for(const l of layers){if(!l.visible)continue;context(c).globalAlpha=l.opacity;context(c).globalCompositeOperation=l.blend;context(c).drawImage(l.canvas,0,0,c.width,c.height);}return c.toDataURL('image/png');}
