  const encodedMasks=new WeakMap();
  function encodedMask(l){if(!l.mask)return Promise.resolve(null);if(encodedMasks.has(l.mask))return encodedMasks.get(l.mask);const result=new Promise((resolve,reject)=>maskCanvas(l.mask).toBlob(b=>b?resolve(b):reject(Error('Не удалось записать маску.')),'image/png'));encodedMasks.set(l.mask,result);return result;}
  async function loadMask(l,w,h,blob=false){if(!l.mask)return null;if(blob&&(!(l.mask instanceof Blob)||l.mask.type!=='image/png'))throw Error('Повреждённая маска.');if(!blob&&(typeof l.mask!=='string'||!l.mask.startsWith('data:image/png;base64,')))throw Error('Повреждённая маска.');const url=blob?URL.createObjectURL(l.mask):l.mask;let image;try{image=await decodeUrl(url);}finally{if(blob)URL.revokeObjectURL(url);}if(image.naturalWidth!==w||image.naturalHeight!==h)throw Error('Размер маски не совпадает с листом.');const c=canvas(w,h);context(c).drawImage(image,0,0);const data=context(c).getImageData(0,0,w,h).data;return Uint8Array.from({length:w*h},(_,i)=>Number(data[i*4+3]>=128));}

