  $('zoomOut').onclick=()=>setZoom(zoom/1.25);$('zoomIn').onclick=()=>setZoom(zoom*1.25);$('zoom100').onchange=()=>setZoom(Number($('zoom100').value)/100);$('fit').onclick=fit;
