  $('addLayer').onclick=()=>{if(!canAdd())return;const s=layerSnapshot(),l=layer();layers.splice(layers.indexOf(active())+1,0,l);activeId=l.id;changed(s);};
  $('duplicateLayer').onclick=()=>{if(!canAdd())return;const s=layerSnapshot(),src=active(),l=layer(src.name+' — копия');Object.assign(l,{visible:src.visible,locked:src.locked,opacity:src.opacity,blend:src.blend});context(l.canvas).drawImage(src.canvas,0,0);l.mask=src.mask?.slice()||null;l.maskEnabled=!!src.maskEnabled;l.alphaLocked=!!src.alphaLocked;l.paper=!!src.paper;layers.splice(layers.indexOf(src)+1,0,l);activeId=l.id;changed(s);};
  $('deleteLayer').onclick=()=>{if(layers.length<=1)return;if(active().locked){tell('Сначала снимите защиту слоя.');return;}const s=layerSnapshot(),i=layers.indexOf(active());layers.splice(i,1);activeId=layers[Math.min(i,layers.length-1)].id;changed(s);};
  function reorder(delta){const i=layers.indexOf(active()),j=i+delta;if(j<0||j>=layers.length)return;const s=layerSnapshot();[layers[i],layers[j]]=[layers[j],layers[i]];changed(s);}
