  $('colorHex').onchange=()=>{let v=$('colorHex').value.trim();if(!v.startsWith('#'))v='#'+v;if(/^#[0-9a-f]{6}$/i.test(v))setColor(v);else{$('colorHex').value=$('color').value.toUpperCase();tell('Цвет вводится как #RRGGBB.');}};
